import{_ as t,o as n,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy role ownership","description":"The current GDD and baseline define scope.\\nCurrent authorization is documentation and necessary preparation only; final owner approval is required before game development.\\nThe","frontmatter":{"title":"Chainy role ownership","description":"The current GDD and baseline define scope.\\nCurrent authorization is documentation and necessary preparation only; final owner approval is required before game development.\\nThe","source":"docs/team-delegation.md","category":"Delivery & team","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/team-delegation.md","filePath":"content/docs/team-delegation.md"}'),i={name:"content/docs/team-delegation.md"};function r(s,e,d,c,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-role-ownership">Chainy role ownership<a class="header-anchor" href="#chainy-role-ownership" aria-label="Link to this section">​</a></h1><p>The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a> and <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> define scope. <strong>Current authorization is documentation and necessary preparation only; final owner approval is required before game development.</strong> The <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">readiness plan</a> prepares future execution without starting it. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/team-delegation.html">previous role guide</a> preserves historical scope and dates.</p><h2 id="five-responsibility-lanes">Five responsibility lanes<a class="header-anchor" href="#five-responsibility-lanes" aria-label="Link to this section">​</a></h2><p>Every card has one named owner in one lane. Do not add helpers or reviewers as card owners; use an explicit handoff when another role must act.</p><table><thead><tr><th>Person</th><th>Owns</th></tr></thead><tbody><tr><td>Sherwin Limosnero</td><td>Project coordination, schedule and scope decisions, game design, learner experience, readiness decisions and school/community arrangements</td></tr><tr><td>Christian Jude Villaber</td><td>Game code, data and SQLite behavior, builds, technical integration and technical checks</td></tr><tr><td>Luis Cabrido III</td><td>Art assets, editable sources, exports, naming and asset provenance</td></tr><tr><td>Sean Matthew Narvaez</td><td>All authored project documentation, lesson copy, guides, instructions, test forms, manuscript and evidence reports</td></tr><tr><td>Miguel De Leon</td><td>Game UI implementation and adjustment using the approved rules, copy and art handoffs</td></tr></tbody></table><p>Design approval does not authorize implementation before the final development decision. Supplying technical facts, assets or UI artifacts to Sean does not transfer authorship of project documents. Reviewing another lane&#39;s output does not create joint card ownership.</p><h2 id="how-work-passes-between-roles">How work passes between roles<a class="header-anchor" href="#how-work-passes-between-roles" aria-label="Link to this section">​</a></h2><ol><li>The owner records the required artifact and its verification on their card.</li><li>If another lane must continue, create or identify its separate handoff card and finish-to-start dependency.</li><li>The receiving owner checks the input and records work in their own lane.</li><li>Missing inputs remain visible as blockers; a specification or changed deadline does not complete implementation.</li></ol><p>Christian coordinates shared technical integration. Independent future agent packets may run in parallel only after authorization, with stable inputs and nonoverlapping file ownership. Agents do not become board accounts or replace the five human responsibility lanes. The <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">baseline&#39;s dated audit</a> records known source evidence; it does not establish a tested Android build.</p><h2 id="board-and-schedule">Board and schedule<a class="header-anchor" href="#board-and-schedule" aria-label="Link to this section">​</a></h2><p>Use the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a> and its <a href="/Chainy-Docs/content/docs/team-board-guide.html">guide</a> for edits, actual status, dates and named history. GitHub issues are queued execution copies; <code>backlog.json</code> is the publication snapshot. Board accounts are separate from offline learner profiles, and owner names do not imply GitHub accounts.</p><p>Archive superseded economy work, teacher services, exports and standalone Wordle/BlockMatch through the board while retaining their history. They are outside the current game scope. Preserve evidence of completed work without treating it as acceptance of the new design. Rebaseline unfinished work after documentation review.</p><p><strong>Pre-final remains November 21, 2026.</strong> Keep integration, device QA, manuscript and rehearsal work visible. The actual November 10 session outcome remains unverified; neither a scheduled event nor this role map establishes readiness or feasibility.</p></div>',1)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
